package com.dsmod.probe;

import java.io.BufferedReader;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.lang.reflect.Constructor;
import java.lang.reflect.Field;
import java.lang.reflect.Member;
import java.lang.reflect.Method;
import java.util.HashMap;
import java.util.Map;
import java.util.zip.GZIPInputStream;

/**
 * Mainland 2.7.1 (code287) runs the reviewed 2.4.1 (code257) feature code through this
 * translation layer.  Every 2.4.1 symbol (class, field, method) is translated with a table
 * generated by a structural diff of the two official APKs (host/map in the source tree).
 *
 * <p>Fail-closed rules: a 2.4.1 obfuscated class that has no confident 2.7.1 counterpart becomes an
 * unloadable name; a member with no confident counterpart throws NoSuchMethod/NoSuchField, which
 * every hook installer already treats as "feature unavailable".  Nothing is ever guessed at
 * runtime.</p>
 */
final class HostRemap {
    private static volatile String TABLE = "hostmap287.txt.gz";
    private static volatile int hostCode = 287;
    /** Raw 2.7.1 (287) literal -> this host, from T lines (2.7.2 tables only). */
    private static final Map<String, String> T287 = new HashMap<>();
    private static final Map<String, String> T287M = new HashMap<>();
    private static volatile boolean loaded;
    private static volatile boolean active;
    /** old (257) class -> new (287) class, binary names with '/' replaced by '.'. */
    private static final Map<String, String> CLS = new HashMap<>();
    private static final Map<String, String> RCLS = new HashMap<>();
    /** old class -> (old field -> new field). */
    private static final Map<String, Map<String, String>> FLD = new HashMap<>();
    private static final Map<String, Map<String, String>> RFLD = new HashMap<>();
    /** old class -> ("oldName(oldArgs)" -> new name). */
    private static final Map<String, Map<String, String>> MTH = new HashMap<>();
    /** new class -> ("newName(newArgs)" -> old name). */
    private static final Map<String, Map<String, String>> RMTH = new HashMap<>();
    // Hand-audited method relocations (N lines): "oldCls.oldName/arity" -> {newCls, newName, newArgs}
    private static final Map<String, java.util.List<String[]>> NREL = new HashMap<>();
    // reverse: "newCls.newName(newArgs)" -> oldName
    private static final Map<String, String> RNREL = new HashMap<>();
    private static final java.util.List<Object[]> PENDING_REV = new java.util.ArrayList<>();

    private HostRemap() {}

    static boolean active() {
        return active;
    }

    /** Enable the 2.4.1 -> 2.7.1 translation. Returns false if the table is missing. */
    /** Select the table for a detected 2.7.x host (287 mainland 2.7.1, 289 mainland 2.7.2, 290 Google Play 2.7.2). */
    static synchronized boolean activate(int code) {
        if (!loaded) { hostCode = code; TABLE = "hostmap" + code + ".txt.gz"; }
        return activate();
    }

    static int hostCode() {
        return hostCode;
    }

    /** Class name a raw 2.7.1 literal has on this host (identity on 287, null when unknown). */
    static String raw287(String cls) {
        if (hostCode == 287) return cls;
        return T287.get(cls);
    }

    static String raw287Method(String cls, String method) {
        if (hostCode == 287) return method;
        String m = T287M.get(cls + "." + method);
        return m != null ? m : method;
    }

    static synchronized boolean activate() {
        if (loaded) return active;
        loaded = true;
        try (InputStream raw = HostRemap.class.getClassLoader().getResourceAsStream(TABLE)) {
            if (raw == null) return false;
            BufferedReader in = new BufferedReader(new InputStreamReader(new GZIPInputStream(raw), "UTF-8"));
            String line, cur = null, curNew = null;
            Map<String, String> f = null, rf = null, m = null, rm = null;
            while ((line = in.readLine()) != null) {
                if (line.isEmpty()) continue;
                String[] p = line.split(" ");
                switch (p[0]) {
                    case "C":
                        cur = p[1].replace('/', '.');
                        curNew = p[2].replace('/', '.');
                        CLS.put(cur, curNew);
                        RCLS.put(curNew, cur);
                        f = new HashMap<>(); rf = new HashMap<>();
                        m = new HashMap<>(); rm = new HashMap<>();
                        FLD.put(cur, f); RFLD.put(curNew, rf);
                        MTH.put(cur, m); RMTH.put(curNew, rm);
                        break;
                    case "F":
                        if (p.length == 2) { f.put(p[1], p[1]); rf.put(p[1], p[1]); }
                        else { f.put(p[1], p[2]); rf.put(p[2], p[1]); }
                        break;
                    case "M": {
                        // M oldName (oldArgs)oldRet newName
                        String oldName = p[1];
                        String desc = p[2];
                        String newName = p[3];
                        String oldArgs = desc.substring(0, desc.indexOf(')') + 1);
                        m.put(oldName + oldArgs, newName);
                        // reverse key uses translated args; translated after the whole table is
                        // read, because arg classes may be declared later in the file.
                        PENDING_REV.add(new Object[]{rm, newName, oldArgs, oldName});
                        break;
                    }
                    case "A": {
                        // A oldCls newCls : forward-only alias for an R8 utility bag that was
                        // split; lets a hook load the class whose single audited method an N
                        // line relocates. No reverse class mapping is recorded.
                        if (p.length >= 3 && !CLS.containsKey(p[1])) CLS.put(p[1], p[2]);
                        break;
                    }
                    case "N": {
                        // N oldCls oldName (oldArgs) newCls newName (newArgs)   args space-separated
                        int a = line.indexOf('('), b = line.indexOf(')');
                        String[] head = line.substring(0, a).trim().split(" ");
                        String oldArgs = line.substring(a + 1, b).trim();
                        String rest = line.substring(b + 1).trim();
                        int c2 = rest.indexOf('('), d2 = rest.lastIndexOf(')');
                        String[] nh = rest.substring(0, c2).trim().split(" ");
                        String newArgs = rest.substring(c2 + 1, d2).trim();
                        String na = descJoin(newArgs);
                        int arity = oldArgs.isEmpty() ? 0 : oldArgs.split(" ").length;
                        String key = head[1].replace('/', '.') + "." + head[2] + "/" + arity;
                        java.util.List<String[]> l = NREL.get(key);
                        if (l == null) { l = new java.util.ArrayList<>(); NREL.put(key, l); }
                        String newCls = nh[0].replace('/', '.');
                        l.add(new String[]{newCls, nh[1], na});
                        RNREL.put(newCls + "." + nh[1] + na, head[2]);
                        break;
                    }
                    case "T": {
                        // T old287 newHost m=n ... : raw 2.7.1 literal used by v271-only paths
                        if (p.length >= 3 && !"None".equals(p[2])) {
                            T287.put(p[1], p[2]);
                            for (int i = 3; i < p.length; i++) {
                                int eq = p[i].indexOf('=');
                                if (eq > 0) T287M.put(p[1] + "." + p[i].substring(0, eq), p[i].substring(eq + 1));
                            }
                        }
                        break;
                    }
                    default:
                        break;
                }
            }
            for (Object[] e : PENDING_REV) {
                @SuppressWarnings("unchecked") Map<String, String> rev = (Map<String, String>) e[0];
                rev.put((String) e[1] + translateDesc((String) e[2]), (String) e[3]);
            }
            PENDING_REV.clear();
            active = true;
        } catch (Throwable t) {
            Main.log("HostRemap load failed: " + t);
            active = false;
        }
        return active;
    }

    /** "Ljava/lang/String; Z Lph5;" -> "(Ljava.lang.String;ZLph5;)" (dotted, as descOf builds). */
    private static String descJoin(String spaced) {
        StringBuilder b = new StringBuilder("(");
        if (!spaced.isEmpty()) for (String t : spaced.split(" ")) b.append(t.replace('/', '.'));
        return b.append(')').toString();
    }

    /** Audited relocation for a lookup on live class c, or null. Matches exact live arg types. */
    private static String relocated(Class<?> c, String oldName, Class<?>[] types) {
        String oldCls = RCLS.get(c.getName());
        if (oldCls == null) return null;
        java.util.List<String[]> l = NREL.get(oldCls + "." + oldName + "/" + types.length);
        if (l == null) return null;
        String args = descOf(types);
        for (String[] e : l) if (e[0].equals(c.getName()) && e[2].equals(args)) return e[1];
        return null;
    }

    private static boolean obf(String name) {
        if (name == null) return false;
        int dollar = name.indexOf('$');
        String base = dollar >= 0 ? name.substring(0, dollar) : name;
        if (base.indexOf('.') >= 0 || base.isEmpty() || base.length() > 4) return false;
        for (int i = 0; i < base.length(); i++) {
            char c = base.charAt(i);
            if (!((c >= 'a' && c <= 'z') || (c >= '0' && c <= '9'))) return false;
        }
        return true;
    }

    /** Translate a 2.4.1 class name. Non-obfuscated names are returned unchanged. */
    static String cls(String oldName) {
        if (!active || oldName == null) return oldName;
        if (oldName.startsWith(HostCompat.UNMAPPED_PREFIX)) return oldName;
        if (!obf(oldName)) return oldName;
        String n = CLS.get(oldName);
        return n != null ? n : HostCompat.UNMAPPED_PREFIX + oldName;
    }

    private static String translateDesc(String oldArgs) {
        StringBuilder b = new StringBuilder();
        int i = 0;
        while (i < oldArgs.length()) {
            char c = oldArgs.charAt(i);
            if (c == 'L') {
                int e = oldArgs.indexOf(';', i);
                String t = oldArgs.substring(i + 1, e).replace('/', '.');
                String n = CLS.get(t);
                b.append('L').append(n != null ? n : (obf(t) ? "?" + t : t)).append(';');
                i = e + 1;
            } else {
                b.append(c);
                i++;
            }
        }
        return b.toString().replace('/', '.');
    }

    private static String descOf(Class<?>[] types) {
        StringBuilder b = new StringBuilder("(");
        for (Class<?> t : types) b.append(descOf(t));
        return b.append(')').toString();
    }

    private static String descOf(Class<?> t) {
        if (t.isArray()) return "[" + descOf(t.getComponentType());
        if (t == int.class) return "I";
        if (t == boolean.class) return "Z";
        if (t == long.class) return "J";
        if (t == float.class) return "F";
        if (t == double.class) return "D";
        if (t == byte.class) return "B";
        if (t == char.class) return "C";
        if (t == short.class) return "S";
        if (t == void.class) return "V";
        return "L" + t.getName() + ";";
    }

    /** New (287) method name for an old-name lookup on a live 287 class, or null. */
    private static String methodName(Class<?> c, String oldName, Class<?>[] types) {
        String args = descOf(types);
        for (Class<?> k = c; k != null; k = k.getSuperclass()) {
            String r = relocated(k, oldName, types);
            if (r != null) return r;
        }
        for (Class<?> k = c; k != null; k = k.getSuperclass()) {
            Map<String, String> rm = RMTH.get(k.getName());
            if (rm == null) continue;
            String oldCls = RCLS.get(k.getName());
            Map<String, String> m = MTH.get(oldCls);
            // Find the old entry whose translated args equal the live args.
            for (Map.Entry<String, String> e : rm.entrySet()) {
                String key = e.getKey();
                if (e.getValue().equals(oldName) && key.endsWith(args)
                        && key.length() == key.indexOf('(') + args.length()) {
                    return key.substring(0, key.indexOf('('));
                }
            }
        }
        return null;
    }

    private static boolean hostClass(Class<?> c) {
        for (Class<?> k = c; k != null; k = k.getSuperclass()) {
            if (RCLS.containsKey(k.getName()) || obf(k.getName())) return true;
        }
        return false;
    }

    static Method declaredMethod(Class<?> c, String name, Class<?>... types)
            throws NoSuchMethodException {
        if (!active || !obf(c.getName())) return c.getDeclaredMethod(name, types);
        String n = methodName(c, name, types);
        if (n == null) throw new NoSuchMethodException("deekseep unmapped " + c.getName() + "." + name);
        return c.getDeclaredMethod(n, types);
    }

    static Method method(Class<?> c, String name, Class<?>... types) throws NoSuchMethodException {
        if (!active || !hostClass(c)) return c.getMethod(name, types);
        String n = methodName(c, name, types);
        if (n == null) {
            // Public framework/Kotlin methods inherited by host classes keep their names.
            try {
                Method m = c.getMethod(name, types);
                if (!obf(m.getDeclaringClass().getName())) return m;
            } catch (NoSuchMethodException ignored) {}
            throw new NoSuchMethodException("deekseep unmapped " + c.getName() + "." + name);
        }
        return c.getMethod(n, types);
    }

    private static String fieldName(Class<?> c, String oldName) {
        for (Class<?> k = c; k != null; k = k.getSuperclass()) {
            String oldCls = RCLS.get(k.getName());
            if (oldCls == null) continue;
            Map<String, String> f = FLD.get(oldCls);
            if (f != null && f.containsKey(oldName)) return f.get(oldName);
        }
        return null;
    }

    static Field declaredField(Class<?> c, String name) throws NoSuchFieldException {
        if (!active || !obf(c.getName())) return c.getDeclaredField(name);
        String oldCls = RCLS.get(c.getName());
        Map<String, String> f = oldCls == null ? null : FLD.get(oldCls);
        String n = f == null ? null : f.get(name);
        if (n == null) throw new NoSuchFieldException("deekseep unmapped " + c.getName() + "." + name);
        return c.getDeclaredField(n);
    }

    static Field field(Class<?> c, String name) throws NoSuchFieldException {
        if (!active || !hostClass(c)) return c.getField(name);
        String n = fieldName(c, name);
        if (n == null) throw new NoSuchFieldException("deekseep unmapped " + c.getName() + "." + name);
        return c.getField(n);
    }

    /** The 2.4.1 name of a live member, so name filters written for 2.4.1 keep working. */
    static String name(Member m) {
        if (!active || m == null) return m == null ? null : m.getName();
        Class<?> d = m.getDeclaringClass();
        if (!obf(d.getName())) return m.getName();
        if (m instanceof Field) {
            Map<String, String> rf = RFLD.get(d.getName());
            String o = rf == null ? null : rf.get(m.getName());
            return o != null ? o : "deekseep unmapped " + m.getName();
        }
        if (m instanceof Method) {
            String rn = RNREL.get(d.getName() + "." + m.getName() + descOf(((Method) m).getParameterTypes()));
            if (rn != null) return rn;
            Map<String, String> rm = RMTH.get(d.getName());
            String o = rm == null ? null
                    : rm.get(m.getName() + descOf(((Method) m).getParameterTypes()));
            return o != null ? o : "deekseep unmapped " + m.getName();
        }
        return m.getName();
    }

    /** The 2.4.1 name of a live class (for getClass().getName() comparisons). */
    static String className(Class<?> c) {
        if (c == null) return null;
        if (!active) return c.getName();
        String o = RCLS.get(c.getName());
        return o != null ? o : (obf(c.getName()) ? "deekseep unmapped " + c.getName() : c.getName());
    }

    /** 2.4.1 simple name of a live class (getSimpleName() comparisons). */
    static String simpleName(Class<?> c) {
        if (c == null) return null;
        if (!active) return c.getSimpleName();
        String o = RCLS.get(c.getName());
        if (o != null) return o.substring(o.lastIndexOf('.') + 1);
        return obf(c.getName()) ? "deekseep unmapped " + c.getName() : c.getSimpleName();
    }

    static Class<?> load(ClassLoader cl, String oldName) throws ClassNotFoundException {
        return cl.loadClass(cls(oldName));
    }

    static Class<?> forName(String oldName, boolean init, ClassLoader cl) throws ClassNotFoundException {
        return Class.forName(cls(oldName), init, cl);
    }

    /** Name-collision overloads produced by the source rewriter for non-reflection variables. */
    static String name(java.io.File f) {
        return f == null ? null : f.getName();
    }

    static Class<?> forName(String oldName) throws ClassNotFoundException {
        return Class.forName(cls(oldName));
    }

    static int classCount() {
        return CLS.size();
    }
}
